CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(80) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, client_name VARCHAR(180), manager_id BIGINT, start_date DATE, end_date DATE, status VARCHAR(50), budget DECIMAL(14,2), progress TINYINT DEFAULT 0, FOREIGN KEY(manager_id) REFERENCES users(id));
CREATE TABLE tasks (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, title VARCHAR(180) NOT NULL, assignee_id BIGINT, priority VARCHAR(30), due_date DATE, status VARCHAR(40), description TEXT, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(assignee_id) REFERENCES users(id));
CREATE TABLE expenses (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, category VARCHAR(100), amount DECIMAL(14,2) NOT NULL, incurred_on DATE, notes TEXT, created_by BIGINT NOT NULL, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE milestones (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, title VARCHAR(180) NOT NULL, due_date DATE, status VARCHAR(40), approved_at DATETIME NULL, FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE project_documents (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, storage_key VARCHAR(255) NOT NULL, visibility VARCHAR(30) NOT NULL DEFAULT 'internal', uploaded_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(uploaded_by) REFERENCES users(id));
